       2	/*
       3	 * some fairly slow code that needs optimization. This walks the list
       4	 * of all the inodes with pending delalloc and forces them to disk.
       5	 */
       6	static int start_delalloc_inodes(struct btrfs_root *root,
       7					 struct writeback_control *wbc, bool snapshot,
       8					 bool in_reclaim_context)
       9	{
      10		struct btrfs_inode *binode;
      11		struct inode *inode;
      12		struct btrfs_delalloc_work *work, *next;
      13		struct list_head works;
      14		struct list_head splice;
      15		int ret = 0;
      16		bool full_flush = wbc->nr_to_write == LONG_MAX;
      17	
      18		INIT_LIST_HEAD(&works);
      19		INIT_LIST_HEAD(&splice);
      20	
      21		mutex_lock(&root->delalloc_mutex);
      22		spin_lock(&root->delalloc_lock);
      23		list_splice_init(&root->delalloc_inodes, &splice);
      24		while (!list_empty(&splice)) {
      25			binode = list_entry(splice.next, struct btrfs_inode,
      26					    delalloc_inodes);
      27	
      28			list_move_tail(&binode->delalloc_inodes,
      29				       &root->delalloc_inodes);
      30	
      31			if (in_reclaim_context &&
      32			    test_bit(BTRFS_INODE_NO_DELALLOC_FLUSH, &binode->runtime_flags))
      33				continue;
      34	
      35			inode = igrab(&binode->vfs_inode);
      36			if (!inode) {
      37				cond_resched_lock(&root->delalloc_lock);
      38				continue;
      39			}
      40			spin_unlock(&root->delalloc_lock);
      41	
      42			if (snapshot)
      43				set_bit(BTRFS_INODE_SNAPSHOT_FLUSH,
      44					&binode->runtime_flags);
      45			if (full_flush) {
      46				work = btrfs_alloc_delalloc_work(inode);
      47				if (!work) {
      48					iput(inode);
      49					ret = -ENOMEM;
      50					goto out;
      51				}
      52				list_add_tail(&work->list, &works);
      53				btrfs_queue_work(root->fs_info->flush_workers,
      54						 &work->work);
      55			} else {
      56				ret = sync_inode(inode, wbc);
      57				if (!ret &&
      58				    test_bit(BTRFS_INODE_HAS_ASYNC_EXTENT,
      59					     &BTRFS_I(inode)->runtime_flags))
      60					ret = sync_inode(inode, wbc);
      61				btrfs_add_delayed_iput(inode);
      62				if (ret || wbc->nr_to_write <= 0)
      63					goto out;
      64			}
      65			cond_resched();
      66			spin_lock(&root->delalloc_lock);
      67		}
      68		spin_unlock(&root->delalloc_lock);
      69	
      70	out:
      71		list_for_each_entry_safe(work, next, &works, list) {
      72			list_del_init(&work->list);
      73			wait_for_completion(&work->completion);
      74			kfree(work);
      75		}
      76	
      77		if (!list_empty(&splice)) {
      78			spin_lock(&root->delalloc_lock);
      79			list_splice_tail(&splice, &root->delalloc_inodes);
      80			spin_unlock(&root->delalloc_lock);
      81		}
      82		mutex_unlock(&root->delalloc_mutex);
      83		return ret;
      84	}
